<?php
if(!defined('ABSPATH'))exit;
final class Hamnna_Report{
 public static function init(){add_action('admin_footer',[__CLASS__,'render']);}
 public static function render(){if(!is_admin()||!isset($_GET['page'])||$_GET['page']!=='hamnna-scraper'||!current_user_can('manage_woocommerce'))return;$logs=get_option('hamnna_scraper_logs',[]);if(!is_array($logs))$logs=[];$runs=[];$tot=['checked'=>0,'new'=>0,'existing'=>0,'unavailable'=>0,'errors'=>0,'seconds'=>0,'count'=>0];foreach($logs as $x){if(!empty($x['price_sync'])||!isset($x['checked']))continue;$runs[]=$x;foreach(['checked','new','existing','unavailable','errors'] as $k)$tot[$k]+=absint($x[$k]??0);$tot['seconds']+=(float)($x['seconds']??0);$tot['count']++;} $last=$runs[0]??[];echo '<style>.ham-report-panel{background:#fff;border:1px solid #d9e2d9;border-radius:16px;padding:24px;margin-top:16px;box-shadow:0 5px 20px rgba(86,159,96,.08)}.ham-report-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px;margin:18px 0}.ham-report-card{padding:16px;border:1px solid #d9e2d9;border-radius:14px;background:#fff}.ham-report-card b{display:block;font-size:24px;color:#569f60;margin-top:6px}.ham-report-table{width:100%;border-collapse:collapse}.ham-report-table th,.ham-report-table td{padding:10px;border-bottom:1px solid #eee;text-align:right}.ham-report-ok{color:#569f60;font-weight:700}.ham-report-muted{opacity:.7}.ham-report-bar{height:10px;background:#eee;border-radius:10px;overflow:hidden;margin:8px 0}.ham-report-bar span{display:block;height:100%;background:#569f60}.ham-report-actions{display:flex;gap:8px;flex-wrap:wrap;margin:15px 0}</style><div id="ham-report-panel" class="ham-report-panel" style="display:none" dir="rtl"><h2>۳. گزارش اسکرپ</h2><p>گزارش مستقل اجرای اسکرپر محصولات؛ شامل آمار تجمعی، آخرین اجرا و جزئیات ۱۰۰ اجرای اخیر.</p><div class="ham-report-actions"><button type="button" class="button" id="ham-report-refresh">به‌روزرسانی گزارش</button><button type="button" class="button" id="ham-report-print">چاپ گزارش</button></div><div class="ham-report-cards"><div class="ham-report-card">کل اجراها<b>'.esc_html($tot['count']).'</b></div><div class="ham-report-card">کل بررسی<b>'.esc_html($tot['checked']).'</b></div><div class="ham-report-card">محصول جدید<b>'.esc_html($tot['new']).'</b></div><div class="ham-report-card">قبلاً موجود<b>'.esc_html($tot['existing']).'</b></div><div class="ham-report-card">ناموجود<b>'.esc_html($tot['unavailable']).'</b></div><div class="ham-report-card">خطا<b>'.esc_html($tot['errors']).'</b></div></div><div class="ham-report-panel" style="padding:16px"><strong>آخرین وضعیت:</strong> '.esc_html(!empty($last['time'])?$last['time']:'هنوز اجرایی ثبت نشده').'</div><h3>جزئیات اجراها</h3><table class="ham-report-table"><thead><tr><th>زمان</th><th>بررسی</th><th>جدید</th><th>موجود قبلی</th><th>ناموجود</th><th>خطا</th><th>مدت</th></tr></thead><tbody>';foreach(array_slice($runs,0,100) as $x)echo '<tr><td>'.esc_html($x['time']??'').'</td><td>'.esc_html($x['checked']??0).'</td><td class="ham-report-ok">'.esc_html($x['new']??0).'</td><td>'.esc_html($x['existing']??0).'</td><td>'.esc_html($x['unavailable']??0).'</td><td>'.esc_html($x['errors']??0).'</td><td>'.esc_html($x['seconds']??0).'s</td></tr>';echo '</tbody></table></div><script>(function(){var tabs=document.querySelector(".ham-tabs");if(!tabs)return;var b=document.createElement("button");b.type="button";b.className="ham-tab";b.textContent="۳. گزارش اسکرپ";tabs.appendChild(b);var p=document.getElementById("ham-report-panel");var panels=document.querySelectorAll(".ham-panel");b.addEventListener("click",function(){panels.forEach(function(x){x.style.display="none"});document.querySelectorAll(".ham-tab").forEach(function(x){x.classList.remove("active")});p.style.display="block";b.classList.add("active")});document.getElementById("ham-report-refresh").addEventListener("click",function(){location.reload()});document.getElementById("ham-report-print").addEventListener("click",function(){window.print()})})();</script>';}
}
Hamnna_Report::init();
